import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = 270005;
    static int n, k, mod;
    static int[][] f = new int[19][MAXN];
    static List<Long> g;
    static int[] cnt = new int[MAXN];
    static int[] jc = new int[MAXN];
    static int[] inv = new int[MAXN];
    static int m, l;
    static long[] C;

    static int upd(int x) {
        if (x < 0) return x + mod;
        if (x >= mod) return x - mod;
        return x;
    }

    static void addRef(int[] x, int y) {
        x[0] = upd(x[0] + y);
    }

    static int ksm(int x, int k) {
        int ans = 1;
        int base = x;
        while (k > 0) {
            if ((k & 1) != 0) ans = (int) ((long) ans * base % mod);
            base = (int) ((long) base * base % mod);
            k >>= 1;
        }
        return ans;
    }

    static void init(int n) {
        jc[0] = 1;
        for (int i = 1; i <= n; i++) {
            jc[i] = (int) ((long) jc[i - 1] * i % mod);
        }
        inv[n] = ksm(jc[n], mod - 2);
        for (int i = n - 1; i >= 0; i--) {
            inv[i] = (int) ((long) inv[i + 1] * (i + 1) % mod);
        }
    }

    static void F(int[] fArr, int n, int h) {
        for (int p = 1; p < n; p <<= 1) {
            for (int i = 0; i < n; i += p << 1) {
                for (int k = i; k < i + p; k++) {
                    addRef(new int[]{fArr[k + p]}, (int) ((long) h * fArr[k] % mod));
                }
            }
        }
    }

    static List<Long> multiply(List<Long> A, List<Long> B) {
        List<Long> C = new ArrayList<>();
        for (int i = 0; i <= l; i++) C.add(0L);
        for (int i = 0; i <= l; i++) {
            for (int j = 0; j <= l - i; j++) {
                long val = C.get(i + j) + A.get(i) * B.get(j);
                C.set(i + j, val % mod);
            }
        }
        return C;
    }

    static List<Long> powsm(List<Long> A, int k) {
        List<Long> C = new ArrayList<>();
        for (int i = 0; i <= l; i++) C.add(0L);
        C.set(0, 1L);
        List<Long> base = new ArrayList<>(A);
        while (k > 0) {
            if ((k & 1) != 0) {
                C = multiply(C, base);
            }
            base = multiply(base, base);
            k >>= 1;
        }
        return C;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        k = Integer.parseInt(st.nextToken());
        mod = Integer.parseInt(st.nextToken());

        init(n);
        if ((n & 1) == 1) {
            System.out.println(ksm(k, n));
            return;
        }

        m = 1;
        while (m <= n) m <<= 1;
        l = 0;
        int temp = m;
        while (temp > 1) {
            temp >>= 1;
            l++;
        }

        for (int i = 0; i < m; i++) {
            cnt[i] = (i >> 1) + (i & 1);
        }

        init(m);
        for (int i = 0; i < m; i++) {
            f[cnt[i]][i] = inv[i];
        }

        for (int i = 0; i < l; i++) {
            F(f[i], m, 1);
        }

        g = new ArrayList<>();
        for (int i = 0; i <= l; i++) g.add(0L);

        for (int s = 0; s < m; s++) {
            for (int i = 0; i <= l; i++) {
                g.set(i, (long) f[i][s]);
            }
            g = powsm(g, k);
            for (int i = 0; i <= l; i++) {
                f[i][s] = g.get(i).intValue();
            }
        }

        F(f[cnt[n]], m, -1);
        int result = upd((int) ((ksm(k, n) - (long) f[cnt[n]][n] * jc[n] % mod + mod) % mod));
        System.out.println(result);
    }
}
